// ——— Construction ———
const parse = (txt) => (txt ?? '').split('|').map((s) => s.trim()).filter(Boolean).map((s) => { const [nom, palier, titre] = s.split('~'); return { nom, palier: Number(palier) || 4, titre: titre ?? nom } })

async function images(wiki, titres, essai = 1) {
  const [nom, langue] = wiki.split('/')
  const base = `https://${nom}.fandom.com${langue ? `/${langue}` : ''}/api.php`
  const p = new URLSearchParams({ action: 'query', format: 'json', redirects: '1', prop: 'pageimages', piprop: 'thumbnail', pithumbsize: '500', titles: titres.join('|') })
  try {
    const r = await fetch(`${base}?${p}`, { headers: UA })
    if (r.status === 429 && essai < 5) { await new Promise((ok) => setTimeout(ok, 6000 * essai)); return images(wiki, titres, essai + 1) }
    if (!r.ok) return new Map()
    const j = await r.json()
    const vers = new Map()
    for (const n of [...(j.query?.normalized ?? []), ...(j.query?.redirects ?? [])]) vers.set(n.from, n.to)
    const parTitre = new Map(Object.values(j.query?.pages ?? {}).filter((pg) => pg.thumbnail).map((pg) => [pg.title, pg.thumbnail.source]))
    const out = new Map()
    for (const t of titres) { let f = t; for (let k = 0; k < 3 && vers.has(f); k++) f = vers.get(f); if (parTitre.has(f)) out.set(t, parTitre.get(f).replace(/\/scale-to-width-down\/\d+/, '/scale-to-width-down/500')) }
    return out
  } catch { return new Map() }
}

// Ordre stable mais mélangé à l'intérieur d'un palier (les jeux se mélangent)
const hash = (s) => [...s].reduce((h, c) => (h * 31 + c.charCodeAt(0)) | 0, 7)

async function construire(type) {
  const items = []
  const manquants = []
  for (const j of JEUX) {
    const liste = parse(j[type])
    if (!liste.length) continue
    const imgs = new Map()
    for (let i = 0; i < liste.length; i += 50) for (const [k, v] of await images(j.wiki, liste.slice(i, i + 50).map((x) => x.titre))) imgs.set(k, v)
    for (const x of liste) {
      const img = imgs.get(x.titre)
      if (!img) { manquants.push(`${x.nom} (${j.jeu})`); continue }
      items.push({ id: `${type[0]}-${hash(j.jeu + x.nom).toString(36)}`, n: { fr: x.nom, en: x.titre }, r: { fr: j.jeu, en: j.jeu }, img, x: { genre: j.g }, p: x.palier, g: j.jeu })
    }
    await new Promise((ok) => setTimeout(ok, 300))
  }
  items.sort((a, b) => a.p - b.p || hash(a.id) - hash(b.id))
  const vus = new Set()
  const uniques = items.filter((it) => !vus.has(it.id) && vus.add(it.id)).map(({ p, ...it }) => it) // eslint-disable-line no-unused-vars
  const fichier = type === 'persos' ? 'persos-jeu' : 'lieux-jeux'
  await writeFile(`public/packs/culture/${fichier}.json`, JSON.stringify(uniques))
  const paliers = [1, 2, 3, 4].map((p) => items.filter((it) => it.p === p).length)
  console.log(`${fichier} : ${uniques.length} (paliers ${paliers.join(' / ')}) · sans image : ${manquants.length}`)
  if (manquants.length) console.log(`  sans image : ${manquants.slice(0, 40).join(', ')}${manquants.length > 40 ? '…' : ''}`)
}

await construire('persos')
await construire('lieux')
